  external_drug_name?: string | null;
  external_strength?: string | null;
  external_form?: string | null;
  /** In lowest units (e.g. 15 tablets) */
  qty_prescribed: number | string;
  dose_text?: string | null;
  route?: "Oral" | "IV" | "IM" | "SC" | "Topical" | "Inhaled" | "PR" | "SL" | "Ophthalmic" | "Otic" | "Nasal" | "Other" | null;
  frequency_code?: "OD" | "BD" | "TDS" | "QID" | "Q4H" | "Q6H" | "Q8H" | "Q12H" | "HS" | "STAT" | "PRN" | "Other" | null;
  interval_hours?: number | null;
  duration_days?: number | null;
  instructions?: string | null;
  /** Required for inpatient orders (MAR) */
  start_at?: string | null;
  end_at?: string | null;
  is_prn?: boolean;
  is_stat?: boolean;
  /** Inpatients: the patient may take it themselves (MSDS 70): an oral, inhaled or topical medicine that is not high-alert, from the hospital pharmacy or bought outside (an outside line with a drug_id of the hospital's list, never a typed name; decisions 59) */
