/** The prescription handed over and the copy kept (the clinic manual, indicator 35). */
export interface HandoverIn {
  handed_to: "Patient" | "Attendant";
  /** Required for an attendant */
  attendant_name?: string | null;
  /** How the establishment keeps its copy: the electronic record, a carbon copy, or the scan of the signed copy in the patient's documents (document_id) */
  copy_kept: "Electronic" | "CarbonCopy" | "Scan";
  /** Scan: the patient's document (doc_type Prescription) */
  document_id?: number | null;
}

/** Cancel (clinical content is never edited) — POST /api/v1/prescriptions/{prescription_id}/cancel (who may call: holders of prescription.cancel). */
export function cancelPrescriptions(prescription_id: number, body: PharmacyReasonIn): Promise<PrescriptionDetailOut> {
  return api<PrescriptionDetailOut>("POST", `/prescriptions/${prescription_id}/cancel`, body);
}

/** Formulary search with live stock colour — GET /api/v1/drugs/search (who may call: holders of pharmacy.formulary.view). */
export function searchDrugs(query?: { q?: string; limit?: number }): Promise<DrugStockOut[]> {
  return api<DrugStockOut[]>("GET", withQuery(`/drugs/search`, query), undefined);
}

/** Drug stock with batches in FEFO order — GET /api/v1/drugs/{drug_id}/stock-status (who may call: holders of pharmacy.formulary.view or pharmacy.stock.view). */
export function stockStatus(drug_id: number): Promise<DrugStockDetailOut> {
  return api<DrugStockDetailOut>("GET", `/drugs/${drug_id}/stock-status`, undefined);
}

/** E-prescription (hospital pharmacy or external slip) — POST /api/v1/prescriptions (who may call: holders of prescription.create). */
export function createPrescription(body: PrescriptionIn): Promise<PrescriptionDetailOut> {
  return api<PrescriptionDetailOut>("POST", `/prescriptions`, body, { idempotent: true });
}

/** Printable prescription slip — GET /api/v1/prescriptions/{prescription_id}/print-payload (who may call: holders of prescription.view). */
export function rxPrint(prescription_id: number): Promise<PrintOut_PrescriptionPrintFieldsOut_> {
  return api<PrintOut_PrescriptionPrintFieldsOut_>("GET", `/prescriptions/${prescription_id}/print-payload`, undefined);
}

/** Record that the prescription was handed to the patient and how its copy is kept — POST /api/v1/prescriptions/{prescription_id}/handover (who may call: holders of prescription.create or pharmacy.dispense). */
export function rxHandover(prescription_id: number, body: HandoverIn): Promise<PrescriptionDetailOut> {
  return api<PrescriptionDetailOut>("POST", `/prescriptions/${prescription_id}/handover`, body, { idempotent: true });
}
